import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.DHmNT4rz.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1784470733000}'),r={name:"guide/configuration.md"};function n(d,e,c,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Environment values are validated at process startup. The complete templates are <a href="https://github.com/mathias7799/SaaSWeave/blob/main/packages/env/.env.example" target="_blank" rel="noreferrer"><code>packages/env/.env.example</code></a> for native development and <a href="https://github.com/mathias7799/SaaSWeave/blob/main/.env.docker.example" target="_blank" rel="noreferrer"><code>.env.docker.example</code></a> for Compose.</p><h2 id="minimum-configuration" tabindex="-1">Minimum configuration <a class="header-anchor" href="#minimum-configuration" aria-label="Permalink to &quot;Minimum configuration&quot;">​</a></h2><p>At minimum, configure the public web and server URLs, <code>DATABASE_URL</code>, and <code>BETTER_AUTH_SECRET</code>. Production deployments also require a shared Redis unless the explicit single-instance fallback is enabled.</p><h2 id="optional-capabilities" tabindex="-1">Optional capabilities <a class="header-anchor" href="#optional-capabilities" aria-label="Permalink to &quot;Optional capabilities&quot;">​</a></h2><p>Provider credentials activate optional capabilities. Each stays off until its configuration is present.</p><table tabindex="0"><thead><tr><th>Capability</th><th>Configuration</th></tr></thead><tbody><tr><td>OAuth</td><td><code>GOOGLE_*</code>, <code>GITHUB_*</code></td></tr><tr><td>Stripe</td><td><code>STRIPE_SECRET_KEY</code>, webhook secret, price and meter maps</td></tr><tr><td>Email</td><td><code>MAIL_PROVIDER=resend</code> or <code>smtp</code> plus provider credentials</td></tr><tr><td>Object storage</td><td><code>MINIO_*</code> / S3-compatible endpoint and bucket</td></tr><tr><td>Image delivery</td><td><code>VITE_IMGPROXY_*</code> and an allowlisted source origin</td></tr><tr><td>Metrics</td><td><code>METRICS_ENABLED</code> and <code>METRICS_BEARER_TOKEN</code></td></tr><tr><td>OpenAPI UI</td><td><code>ENABLE_OPEN_API_DOCS=true</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Never commit populated environment files. The templates exist so that real values stay out of version control.</p></div>',8)])])}const h=t(r,[["render",n]]);export{m as __pageData,h as default};
